-- 세트 594. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set594.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 594, 'Ceph 상태 읽기: ceph -s 의 health·OSD·PG, ceph df, nearfull·full 비율', 'Ceph 클러스터 운영의 첫걸음인 상태 출력 읽기입니다. ceph -s 에서 health 상태, up 과 in 의 OSD 수, 성능 저하(degraded) 비율, active+clean PG 수를 읽고, ceph df 에서 풀별 사용률을 읽고, 용량 경고 비율(nearfull·backfillfull·full)과 풀 복제 설정(size·min_size)의 의미를 정리합니다. 샌드박스에는 Ceph 가 없어 샘플 출력을 읽는 방식이며 수치는 설명용으로 단순화한 값입니다.', 'linux', '스토리지'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 594);
UPDATE quest_set SET display_order = 854, unit_id = (SELECT id FROM unit WHERE id = 21), icon = '🐙' WHERE id = 594;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 1, '클러스터 health 읽기', '`/tmp/ceph_s.log` 는 `ceph -s` 의 출력입니다. `health:` 줄은 클러스터의 전체 상태(HEALTH_OK, HEALTH_WARN, HEALTH_ERR)를 한 단어로 보여 줍니다. 이 클러스터의 **health 값**을 `/tmp/health.txt` 에 저장하세요. (값만)', '`health:` 로 시작하는 줄의 마지막 칸입니다.', 'cat /tmp/ceph_s.log
grep ''health:'' /tmp/ceph_s.log | awk ''{print $2}'' > /tmp/health.txt
cat /tmp/health.txt

# HEALTH_WARN 은 서비스는 되지만 주의가 필요한 상태다. 원인은 그 아래 줄(osds down, degraded)과 ceph health detail 에 나온다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ceph_s.log <<''EOF''\\n  cluster:\\n    id:     0b1c2d3e-0000-0000-0000-000000000000\\n    health: HEALTH_WARN\\n            1 osds down\\n            Degraded data redundancy: 24/300 objects degraded (8.000%), 12 pgs degraded, 12 pgs undersized\\n\\n  services:\\n    mon: 3 daemons, quorum a,b,c (age 4d)\\n    mgr: a(active, since 4d)\\n    osd: 9 osds: 8 up (since 3m), 9 in (since 4d)\\n\\n  data:\\n    pools:   2 pools, 64 pgs\\n    objects: 100 objects, 400 MiB\\n    usage:   3.5 GiB used, 150 GiB / 153 GiB avail\\n    pgs:     24/300 objects degraded (8.000%)\\n             52 active+clean\\n             12 active+undersized+degraded\\nEOF\\ncat > /tmp/ceph_df.log <<''EOF''\\n--- RAW STORAGE ---\\nCLASS     SIZE    AVAIL     USED  RAW USED  %RAW USED\\nhdd    153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\nTOTAL  153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\n\\n--- POOLS ---\\nPOOL   ID  PGS   STORED  OBJECTS     USED  %USED  MAX AVAIL\\nrbd     1   32  300 MiB       75  900 MiB   1.84     48 GiB\\nmeta    2   32  100 MiB       25  300 MiB   0.61     48 GiB\\nEOF\\ncat > /tmp/osd_dump.log <<''EOF''\\nepoch 120\\nfull_ratio 0.95\\nbackfillfull_ratio 0.9\\nnearfull_ratio 0.85\\npool 1 ''rbd'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\npool 2 ''meta'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/health.txt)\\" = HEALTH_WARN ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "HEALTH_WARN 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/health.txt)\\" = HEALTH_WARN ]"]}]', '[{"title": "Ceph 문서: 상태 확인", "url": "https://docs.ceph.com/en/latest/rados/operations/monitoring/"}, {"title": "Ceph 문서: 용량 경고", "url": "https://docs.ceph.com/en/latest/rados/operations/health-checks/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 2, 'OSD 의 up 과 in', '`osd:` 줄은 OSD 개수와 상태를 보여 줍니다. **up** 은 OSD 데몬이 실행 중이라는 뜻이고 **in** 은 데이터 배치에 참여하고 있다는 뜻입니다. **up 인 OSD 수**와 **in 인 OSD 수**를 `/tmp/up.txt`, `/tmp/in.txt` 에 각각 숫자만 저장하세요.', '`osd:` 줄에 `N up`, `N in` 이 있습니다. 앞의 숫자를 뽑으세요.', 'grep ''osd:'' /tmp/ceph_s.log
grep ''osd:'' /tmp/ceph_s.log | grep -o ''[0-9]* up'' | cut -d'' '' -f1 > /tmp/up.txt
grep ''osd:'' /tmp/ceph_s.log | grep -o ''[0-9]* in'' | cut -d'' '' -f1 > /tmp/in.txt
cat /tmp/up.txt /tmp/in.txt

# 9 개 중 8 개만 up 이고 9 개는 in 이다. 한 OSD 가 내려갔지만 아직 in 이라 데이터를 다른 곳에 옮기지 않은 상태다. 일정 시간 뒤에는 out 으로 바뀌어 재분배(backfill)가 시작된다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ceph_s.log <<''EOF''\\n  cluster:\\n    id:     0b1c2d3e-0000-0000-0000-000000000000\\n    health: HEALTH_WARN\\n            1 osds down\\n            Degraded data redundancy: 24/300 objects degraded (8.000%), 12 pgs degraded, 12 pgs undersized\\n\\n  services:\\n    mon: 3 daemons, quorum a,b,c (age 4d)\\n    mgr: a(active, since 4d)\\n    osd: 9 osds: 8 up (since 3m), 9 in (since 4d)\\n\\n  data:\\n    pools:   2 pools, 64 pgs\\n    objects: 100 objects, 400 MiB\\n    usage:   3.5 GiB used, 150 GiB / 153 GiB avail\\n    pgs:     24/300 objects degraded (8.000%)\\n             52 active+clean\\n             12 active+undersized+degraded\\nEOF\\ncat > /tmp/ceph_df.log <<''EOF''\\n--- RAW STORAGE ---\\nCLASS     SIZE    AVAIL     USED  RAW USED  %RAW USED\\nhdd    153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\nTOTAL  153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\n\\n--- POOLS ---\\nPOOL   ID  PGS   STORED  OBJECTS     USED  %USED  MAX AVAIL\\nrbd     1   32  300 MiB       75  900 MiB   1.84     48 GiB\\nmeta    2   32  100 MiB       25  300 MiB   0.61     48 GiB\\nEOF\\ncat > /tmp/osd_dump.log <<''EOF''\\nepoch 120\\nfull_ratio 0.95\\nbackfillfull_ratio 0.9\\nnearfull_ratio 0.85\\npool 1 ''rbd'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\npool 2 ''meta'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/up.txt)\\" = 8 ] ) && ( [ \\"$(cat /tmp/in.txt)\\" = 9 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "up 이 8 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/up.txt)\\" = 8 ]"]}, {"label": "in 이 9 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/in.txt)\\" = 9 ]"]}]', '[{"title": "Ceph 문서: 상태 확인", "url": "https://docs.ceph.com/en/latest/rados/operations/monitoring/"}, {"title": "Ceph 문서: 용량 경고", "url": "https://docs.ceph.com/en/latest/rados/operations/health-checks/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 3, '성능 저하 비율', '`/tmp/ceph_s.log` 의 `ceph -s` 출력에는 복제본이 모자란 객체의 비율이 있습니다. **degraded 객체 비율**(`%` 포함, 예: `1.500%` 모양)을 `/tmp/degraded.txt` 에 저장하세요.', '괄호 안의 퍼센트 값입니다. 같은 문장이 여러 번 나오니 첫 번째만 쓰세요.', 'grep -o ''([0-9.]*%)'' /tmp/ceph_s.log | head -1 | tr -d ''()'' > /tmp/degraded.txt
cat /tmp/degraded.txt

# 복제본(3개)이 일부 없어진 객체의 비율이다. 내려간 OSD 가 돌아오거나 재분배가 끝나면 줄어든다. 이 상태에서 추가 장애가 나면 데이터 손실 위험이 커진다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ceph_s.log <<''EOF''\\n  cluster:\\n    id:     0b1c2d3e-0000-0000-0000-000000000000\\n    health: HEALTH_WARN\\n            1 osds down\\n            Degraded data redundancy: 24/300 objects degraded (8.000%), 12 pgs degraded, 12 pgs undersized\\n\\n  services:\\n    mon: 3 daemons, quorum a,b,c (age 4d)\\n    mgr: a(active, since 4d)\\n    osd: 9 osds: 8 up (since 3m), 9 in (since 4d)\\n\\n  data:\\n    pools:   2 pools, 64 pgs\\n    objects: 100 objects, 400 MiB\\n    usage:   3.5 GiB used, 150 GiB / 153 GiB avail\\n    pgs:     24/300 objects degraded (8.000%)\\n             52 active+clean\\n             12 active+undersized+degraded\\nEOF\\ncat > /tmp/ceph_df.log <<''EOF''\\n--- RAW STORAGE ---\\nCLASS     SIZE    AVAIL     USED  RAW USED  %RAW USED\\nhdd    153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\nTOTAL  153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\n\\n--- POOLS ---\\nPOOL   ID  PGS   STORED  OBJECTS     USED  %USED  MAX AVAIL\\nrbd     1   32  300 MiB       75  900 MiB   1.84     48 GiB\\nmeta    2   32  100 MiB       25  300 MiB   0.61     48 GiB\\nEOF\\ncat > /tmp/osd_dump.log <<''EOF''\\nepoch 120\\nfull_ratio 0.95\\nbackfillfull_ratio 0.9\\nnearfull_ratio 0.85\\npool 1 ''rbd'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\npool 2 ''meta'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/degraded.txt)\\" = \\"8.000%\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "8.000% 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/degraded.txt)\\" = \\"8.000%\\" ]"]}]', '[{"title": "Ceph 문서: 상태 확인", "url": "https://docs.ceph.com/en/latest/rados/operations/monitoring/"}, {"title": "Ceph 문서: 용량 경고", "url": "https://docs.ceph.com/en/latest/rados/operations/health-checks/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 4, '정상인 PG 수', '`pgs:` 구역은 PG(배치 그룹)의 상태별 개수를 보여 줍니다. **`active+clean`**(정상) 상태인 PG 의 개수를 숫자만 `/tmp/clean.txt` 에 저장하세요.', '`active+clean` 앞의 숫자입니다. `active+undersized+degraded` 와 헷갈리지 마세요.', 'grep -E ''[0-9]+ active\\+clean$'' /tmp/ceph_s.log | awk ''{print $1}'' > /tmp/clean.txt
cat /tmp/clean.txt

# 전체 64 개 중 52 개가 정상이고 12 개는 복제본이 모자란(undersized+degraded) 상태다. 모든 PG 가 active+clean 이 되어야 완전히 정상이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ceph_s.log <<''EOF''\\n  cluster:\\n    id:     0b1c2d3e-0000-0000-0000-000000000000\\n    health: HEALTH_WARN\\n            1 osds down\\n            Degraded data redundancy: 24/300 objects degraded (8.000%), 12 pgs degraded, 12 pgs undersized\\n\\n  services:\\n    mon: 3 daemons, quorum a,b,c (age 4d)\\n    mgr: a(active, since 4d)\\n    osd: 9 osds: 8 up (since 3m), 9 in (since 4d)\\n\\n  data:\\n    pools:   2 pools, 64 pgs\\n    objects: 100 objects, 400 MiB\\n    usage:   3.5 GiB used, 150 GiB / 153 GiB avail\\n    pgs:     24/300 objects degraded (8.000%)\\n             52 active+clean\\n             12 active+undersized+degraded\\nEOF\\ncat > /tmp/ceph_df.log <<''EOF''\\n--- RAW STORAGE ---\\nCLASS     SIZE    AVAIL     USED  RAW USED  %RAW USED\\nhdd    153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\nTOTAL  153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\n\\n--- POOLS ---\\nPOOL   ID  PGS   STORED  OBJECTS     USED  %USED  MAX AVAIL\\nrbd     1   32  300 MiB       75  900 MiB   1.84     48 GiB\\nmeta    2   32  100 MiB       25  300 MiB   0.61     48 GiB\\nEOF\\ncat > /tmp/osd_dump.log <<''EOF''\\nepoch 120\\nfull_ratio 0.95\\nbackfillfull_ratio 0.9\\nnearfull_ratio 0.85\\npool 1 ''rbd'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\npool 2 ''meta'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/clean.txt)\\" = 52 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "52 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/clean.txt)\\" = 52 ]"]}]', '[{"title": "Ceph 문서: 상태 확인", "url": "https://docs.ceph.com/en/latest/rados/operations/monitoring/"}, {"title": "Ceph 문서: 용량 경고", "url": "https://docs.ceph.com/en/latest/rados/operations/health-checks/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 5, '가장 많이 쓴 풀', '`/tmp/ceph_df.log` 는 `ceph df` 의 출력입니다. 풀(POOL)별 `%USED` 는 그 풀이 차지한 비율입니다. **`%USED` 가 가장 높은 풀의 이름**을 `/tmp/top_pool.txt` 에 저장하세요.', '`POOLS` 구역의 표에서 `%USED` 열의 숫자를 비교하세요.', 'cat /tmp/ceph_df.log
awk ''/^--- POOLS/{f=1; next} f && /^(rbd|meta)/ {print $1, $(NF-2)}'' /tmp/ceph_df.log | sort -k2 -n -r | head -1 | awk ''{print $1}'' > /tmp/top_pool.txt
cat /tmp/top_pool.txt

# rbd 풀이 1.84% 로 가장 많이 쓴다(%USED 는 끝에서 셋째 칸, MAX AVAIL 값과 단위 앞). 풀의 USED 는 복제본까지 포함한 값(STORED 의 약 3 배)이고 MAX AVAIL 은 복제를 고려한 사용 가능 용량이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ceph_s.log <<''EOF''\\n  cluster:\\n    id:     0b1c2d3e-0000-0000-0000-000000000000\\n    health: HEALTH_WARN\\n            1 osds down\\n            Degraded data redundancy: 24/300 objects degraded (8.000%), 12 pgs degraded, 12 pgs undersized\\n\\n  services:\\n    mon: 3 daemons, quorum a,b,c (age 4d)\\n    mgr: a(active, since 4d)\\n    osd: 9 osds: 8 up (since 3m), 9 in (since 4d)\\n\\n  data:\\n    pools:   2 pools, 64 pgs\\n    objects: 100 objects, 400 MiB\\n    usage:   3.5 GiB used, 150 GiB / 153 GiB avail\\n    pgs:     24/300 objects degraded (8.000%)\\n             52 active+clean\\n             12 active+undersized+degraded\\nEOF\\ncat > /tmp/ceph_df.log <<''EOF''\\n--- RAW STORAGE ---\\nCLASS     SIZE    AVAIL     USED  RAW USED  %RAW USED\\nhdd    153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\nTOTAL  153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\n\\n--- POOLS ---\\nPOOL   ID  PGS   STORED  OBJECTS     USED  %USED  MAX AVAIL\\nrbd     1   32  300 MiB       75  900 MiB   1.84     48 GiB\\nmeta    2   32  100 MiB       25  300 MiB   0.61     48 GiB\\nEOF\\ncat > /tmp/osd_dump.log <<''EOF''\\nepoch 120\\nfull_ratio 0.95\\nbackfillfull_ratio 0.9\\nnearfull_ratio 0.85\\npool 1 ''rbd'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\npool 2 ''meta'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/top_pool.txt)\\" = rbd ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "rbd 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/top_pool.txt)\\" = rbd ]"]}]', '[{"title": "Ceph 문서: 상태 확인", "url": "https://docs.ceph.com/en/latest/rados/operations/monitoring/"}, {"title": "Ceph 문서: 용량 경고", "url": "https://docs.ceph.com/en/latest/rados/operations/health-checks/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 6, 'nearfull 기준 비율', '`/tmp/osd_dump.log` 는 `ceph osd dump` 의 일부입니다. OSD 하나의 사용률이 **nearfull 비율**을 넘으면 경고가 나옵니다. 이 클러스터의 `nearfull_ratio` 값을 `/tmp/nearfull.txt` 에 저장하세요. (값만)', '`ratio` 로 끝나는 설정이 세 가지입니다. 이름에 nearfull 이 들어간 것을 고르세요.', 'cat /tmp/osd_dump.log
grep ''^nearfull_ratio'' /tmp/osd_dump.log | awk ''{print $2}'' > /tmp/nearfull.txt
cat /tmp/nearfull.txt

# 기본은 nearfull 0.85 → backfillfull 0.90 → full 0.95 순이다. full 에 도달하면 쓰기가 막히므로 nearfull 경고 때 바로 용량을 늘리거나 정리한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/ceph_s.log <<''EOF''\\n  cluster:\\n    id:     0b1c2d3e-0000-0000-0000-000000000000\\n    health: HEALTH_WARN\\n            1 osds down\\n            Degraded data redundancy: 24/300 objects degraded (8.000%), 12 pgs degraded, 12 pgs undersized\\n\\n  services:\\n    mon: 3 daemons, quorum a,b,c (age 4d)\\n    mgr: a(active, since 4d)\\n    osd: 9 osds: 8 up (since 3m), 9 in (since 4d)\\n\\n  data:\\n    pools:   2 pools, 64 pgs\\n    objects: 100 objects, 400 MiB\\n    usage:   3.5 GiB used, 150 GiB / 153 GiB avail\\n    pgs:     24/300 objects degraded (8.000%)\\n             52 active+clean\\n             12 active+undersized+degraded\\nEOF\\ncat > /tmp/ceph_df.log <<''EOF''\\n--- RAW STORAGE ---\\nCLASS     SIZE    AVAIL     USED  RAW USED  %RAW USED\\nhdd    153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\nTOTAL  153 GiB  150 GiB  3.5 GiB   3.5 GiB       2.29\\n\\n--- POOLS ---\\nPOOL   ID  PGS   STORED  OBJECTS     USED  %USED  MAX AVAIL\\nrbd     1   32  300 MiB       75  900 MiB   1.84     48 GiB\\nmeta    2   32  100 MiB       25  300 MiB   0.61     48 GiB\\nEOF\\ncat > /tmp/osd_dump.log <<''EOF''\\nepoch 120\\nfull_ratio 0.95\\nbackfillfull_ratio 0.9\\nnearfull_ratio 0.85\\npool 1 ''rbd'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\npool 2 ''meta'' replicated size 3 min_size 2 crush_rule 0 object_hash rjenkins pg_num 32\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/nearfull.txt)\\" = 0.85 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "0.85 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/nearfull.txt)\\" = 0.85 ]"]}]', '[{"title": "Ceph 문서: 상태 확인", "url": "https://docs.ceph.com/en/latest/rados/operations/monitoring/"}, {"title": "Ceph 문서: 용량 경고", "url": "https://docs.ceph.com/en/latest/rados/operations/health-checks/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 7, 'OSD 가 up 이 아니고 in 인 상태', 'OSD 하나가 `down` 이 되었지만 아직 `in` 상태입니다. 이 상태의 의미로 가장 알맞은 것은?', '장애가 난 직후에는 바로 데이터를 옮기지 않고 잠시 기다립니다.', NULL, NULL, '[]', 'choice', '["디스크가 완전히 제거되어 데이터가 모두 삭제되었다", "새 OSD 가 클러스터에 추가되는 중인 상태이다", "데몬은 멈췄지만 구성원으로 남아 재분배가 아직 시작되지 않았다", "OSD 가 정상이며 점검 모드로 잠시 멈춘 것이다"]', 2, 'down 은 데몬이 응답하지 않는다는 뜻이고 in 은 데이터 배치에 포함되어 있다는 뜻입니다. 일정 시간(기본 10분) 뒤에도 돌아오지 않으면 out 으로 바뀌어 다른 OSD 로 복제본을 다시 만듭니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 8, 'size 와 min_size', '풀의 `size 3`, `min_size 2` 설정에서 `min_size` 의 의미로 가장 알맞은 것은?', '복제본이 정상 개수보다 줄어든 PG 가 계속 읽고 쓸 수 있는 조건을 생각해 보세요.', NULL, NULL, '[]', 'choice', '["객체 하나의 최소 크기가 2MB 다", "정상 복제본이 2개 이상일 때만 입출력을 허용한다", "풀에 만들 수 있는 최소 PG 수가 2개다", "복제본을 최소 2개만 만든다"]', 1, 'size 는 목표 복제본 수이고 min_size 는 입출력을 계속하기 위한 최소 복제본 수입니다. 복제본이 min_size 아래로 떨어지면 데이터 안전을 위해 해당 PG 의 입출력이 멈춥니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 9, 'full 비율에 도달하면', 'OSD 가 `full_ratio`(0.95)에 도달했습니다. 클러스터의 동작으로 알맞은 것은?', '데이터를 더 쓰다가 공간이 완전히 바닥나면 어떤 위험이 있을지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["쓰기가 차단되므로 용량을 확보하거나 삭제해야 한다", "읽기까지 모두 차단되어 서비스가 중단된다", "자동으로 가장 오래된 데이터가 삭제된다", "아무 영향이 없고 경고만 표시된다"]', 0, 'full 에 도달하면 데이터 손상을 막으려고 쓰기를 막습니다. 그 전에 nearfull 경고와 backfillfull(재분배 대상 제외)이 먼저 나타납니다. 용량 확보는 OSD 추가, 데이터 삭제, 풀 정리로 합니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 10, '상태를 자세히 보기', '`HEALTH_WARN` 의 **구체적인 원인 목록**을 자세히 보려는 명령입니다. 빈칸을 채우세요.', '`ceph health` 뒤에 붙이는 한 단어입니다.', NULL, NULL, '[]', 'fill', '["detail", "status", "df", "tree"]', NULL, '`ceph health detail` 은 경고별 상세 내용(어느 OSD·PG 가 문제인지)을 보여 줍니다. `ceph -s` 는 요약, `ceph df` 는 용량, `ceph osd tree` 는 OSD 배치(CRUSH 트리)를 보여 줍니다.', '[0]', 'ceph health {0}', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 594, 11, 'Ceph 경고 대응 순서', '`ceph -s` 에서 `HEALTH_WARN` 이 나왔습니다. 요약에서 시작해 원인을 좁히고 조치하려 합니다. 올바른 순서로 놓으세요.', '요약에서 상세로, 원인 확인에서 조치로 이어집니다.', NULL, NULL, '[]', 'order', '["원인에 맞는 조치를 한다(OSD 복구·용량 확보 등)", "`ceph health detail` 로 문제 OSD 번호 등 구체적 원인을 본다", "`ceph -s` 로 전체 상태를 확인한다", "그 OSD 가 어느 호스트에 있는지 `ceph osd tree` 로 확인한다"]', NULL, '전체 요약을 보고, health detail 로 원인을 찾고, osd tree 로 위치를 확인한 뒤 조치합니다. 조치 후에는 다시 `ceph -s` 로 HEALTH_OK 가 되는지 확인합니다.', '[2, 1, 3, 0]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 594 AND order_index = 11);
